create table posts3
(post_id int, 
user_id int ,
content_category varchar (400),
post_text varchar(400) ,
post_date date,
like_count int,
comment_count int, 
share_count int,
view_count int,
hashtag varchar (130),
visibility bit,
device_type varchar (130),
language varchar (120),
engagement_score int,
post_status bit );

