se


Display all posts. 

SELECT * FROM posts3;


Find posts with more than 1,000 views. 
SELECT *
FROM posts
WHERE view_count > 1000;


Sort posts by engagement score. 
SELECT *
FROM posts
ORDER BY engagement_score DESC;


Group posts by content category
SELECT content_category, COUNT(*) AS post_count
FROM posts 
GROUP BY content_category;
